/**
 * Host-side GitHub + Slack clients shared across tools, channel routes,
 * schedules, and channel packs — same injection pattern as MCP.
 */
import { WebClient } from "@slack/web-api";
import { createGitHubOctokit, githubEnterpriseCloudApiBaseUrl } from "../channels/github/api.js";
import { ensureGhCliTokenEnv, hasGitHubAppCredentials, resolveCredentialValue, resolveGitHubInstallationId, tryResolveGhAuthToken, } from "../channels/github/auth.js";
import { slackEnvKeys, tryResolveBotToken } from "../channels/slack/credentials.js";
/** Bot-token Slack client. Pass channel credentials so `envPrefix` is honored. */
export function createHostSlackClient(options = {}) {
    let slackPromise;
    return {
        getClient: async () => {
            slackPromise ??= (async () => {
                const token = await tryResolveBotToken(options.credentials);
                if (token === undefined) {
                    const botKey = slackEnvKeys(options.envPrefix).bot;
                    const hint = options.envPrefix === undefined || options.envPrefix.trim() === ""
                        ? `${botKey} or a channel envPrefix`
                        : botKey;
                    throw new Error(`No Slack bot token available (set ${hint}).`);
                }
                return new WebClient(token);
            })().catch((error) => {
                slackPromise = undefined;
                throw error;
            });
            return slackPromise;
        },
    };
}
/**
 * Build host platforms from ambient credentials. Prefer App installation
 * auth when configured; otherwise fall back to PAT / `gh auth` for local
 * testing. Webhook-scoped calls should still prefer `ctx.github`.
 */
export function createHostPlatforms(options = {}) {
    const octokitPromises = new Map();
    return {
        github: {
            getOctokit: (request) => {
                const enterprise = githubEnterpriseCloudApiBaseUrl(request?.host);
                const key = enterprise ?? "";
                let pending = octokitPromises.get(key);
                if (pending === undefined) {
                    pending = createGitHubOctokit({
                        credentials: options.githubCredentials,
                        host: enterprise === undefined ? undefined : request?.host,
                    }).catch((error) => {
                        octokitPromises.delete(key);
                        throw error;
                    });
                    octokitPromises.set(key, pending);
                }
                return pending;
            },
        },
        slack: createHostSlackClient({
            credentials: options.slackCredentials,
            envPrefix: options.slackEnvPrefix,
        }),
    };
}
/**
 * Detect ambient host GitHub auth without throwing.
 * Order matches {@link createGitHubOctokit}: App installation, then
 * `GITHUB_TOKEN` / `GH_TOKEN`, then `gh auth token`.
 */
export async function resolveHostGitHubAuthSource() {
    if ((await hasGitHubAppCredentials()) && (await resolveGitHubInstallationId()) !== undefined) {
        return "app";
    }
    const fromEnv = (await resolveCredentialValue(process.env.GITHUB_TOKEN)) ??
        (await resolveCredentialValue(process.env.GH_TOKEN));
    if (fromEnv !== undefined) {
        return "env";
    }
    const fromGh = await tryResolveGhAuthToken();
    return fromGh === undefined ? "unavailable" : "gh";
}
/**
 * Soft boot-time GitHub auth check: log the resolved source and optionally
 * prime `github.getOctokit()` so the first request does not pay CLI latency.
 * When auth is App-backed, also export an installation token as `GH_TOKEN`
 * so tools that shell out to `gh` (a host-side `prepare_pr` tool, say)
 * authenticate on corp hosts that have no PAT / `gh
 * auth login`. Never fails serve — missing auth is logged as a warning.
 */
export async function warmupHostGitHubAuth(options) {
    const source = options.authSource ?? (await resolveHostGitHubAuthSource());
    if (source === "unavailable") {
        options.logger("[bdk] GitHub auth: unavailable (set GITHUB_APP_ID + GITHUB_APP_PRIVATE_KEY + GITHUB_APP_INSTALLATION_ID, or GITHUB_TOKEN / GH_TOKEN, or run `gh auth login`)");
        return source;
    }
    let exportedGhToken = false;
    if (source === "app") {
        try {
            exportedGhToken = await ensureGhCliTokenEnv();
        }
        catch (error) {
            options.logger(`[bdk] GitHub auth: failed to export GH_TOKEN for gh CLI: ${error instanceof Error ? error.message : String(error)}`);
        }
    }
    const label = source === "cursor-account"
        ? "Cursor account credential"
        : source === "app"
            ? exportedGhToken
                ? "GitHub App installation token (also exported as GH_TOKEN for gh CLI)"
                : "GitHub App installation token"
            : source === "env"
                ? "GITHUB_TOKEN/GH_TOKEN"
                : "gh auth token";
    if (options.github === undefined) {
        options.logger(`[bdk] GitHub auth: ${label}`);
        return source;
    }
    try {
        await options.github.getOctokit();
        options.logger(`[bdk] GitHub auth: ${label}`);
    }
    catch (error) {
        options.logger(`[bdk] GitHub auth: ${label} resolved but Octokit warmup failed: ${error instanceof Error ? error.message : String(error)}`);
    }
    return source;
}
